"""Base reply for Alexa"""
def create_response(bot_reply: Any, end_of_session: Any = False) -> object {
    response = {
        "version": "1.0",
        "response": {
            "outputSpeech": {"type": "PlainText", "text": bot_reply},
            "reprompt": {
                "outputSpeech": {
                    "type": "PlainText",
                    "text": "Plain text string to speak",
                    "playBehavior": "REPLACE_ENQUEUED"
                }
            },
            "shouldEndSession": end_of_session
        }
    };
    return response;
}

